I = [[1,2,3,0],[0,1,2,3],[3,2,1,0],[0,1,2,1]]
K = [[1,0,-1],[1,0,-1],[1,0,-1]]
S = 1
P = 0
H_out = (4 + 2*P - 3)//S + 1
print(H_out)
out = []
for i in range(H_out):
    row = []
    for j in range(H_out):
        s = 0
        for u in range(3):
            for v in range(3):
                s += I[i*S+u][j*S+v] * K[u][v]
        row.append(s)
    out.append(row)
for row in out:
    for val in row:
        print(val)
